                            {"name": "y", "type": "string"},
                        ],
                    },
                ],
            }
        )
        signature = "F(uint8,bytes4,uint256[][3],(address,string))"
        self.assertEqual(
            event_topic0(event),
            "0x" + keccak256(signature.encode("ascii")).hex(),
